=아래 업체의 당근 소식글 시리즈 컨셉을 잡고 소식글을 생성해줘.

상호명: {{ $json['상호명'] }}
업종/카테고리: {{ $json['업종/카테고리'] }}
지역(시/구/동): {{ $json['지역(시/구/동)'] }}
비즈프로필 링크: {{ $json['비즈프로필 링크(참고용)'] }}
매장/서비스 설명: {{ $json['매장/서비스 설명(자세할수록 좋음)'] }}
핵심/서비스 키워드: {{ $json['핵심/서비스 키워드(선택)'] }}
필수기재 상단: {{ $json['필수기재 상단(선택)'] }}
필수기재 하단: {{ $json['필수기재 하단(선택)'] }}
불포함 키워드: {{ $json['불포함 키워드(선택)'] }}
말투&톤: {{ $json['말투&톤(선택)'] }}
컨셉/주제 힌트: {{ $json['컨셉/주제 힌트(선택)'] }}
생성 개수: {{ $json['생성 개수'] || 5 }}

parameters.jsCode:
// Claude 응답 → 소식글 1건씩 개별 아이템으로 분리
const raw = $json?.content?.[0]?.text ?? $json?.content ?? $json?.text ?? '';
let text = typeof raw === 'string' ? raw : JSON.stringify(raw);
text = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const s = text.indexOf('{'), e = text.lastIndexOf('}');
if (s !== -1 && e !== -1) text = text.slice(s, e + 1);
let d;
try { d = JSON.parse(text); } catch (err) { return [{ json: { 오류: 'JSON 파싱 실패: ' + err.message, 원문: text } }]; }
const f = $('비즈프로필 정보 입력').item.json;
const now = new Date().toISOString();
const posts = Array.isArray(d.posts) ? d.posts : [];
const hj = (v) => Array.isArray(v) ? v.join(' ') : (v ?? '');
return posts.map((p, i) => ({ json: {
  생성시각: now,
  업체명: f['상호명'],
  지역: f['지역(시/구/동)'],
  컨셉: d.concept ?? '',
  순번: i + 1,
  세트: p.set ?? ((i + 1) + '세트'),
  제목: p.title ?? '',
  본문: p.body ?? '',
  핵심키워드: p.primary_keyword ?? '',
  해시태그: hj(p.hashtags),
  링크: f['비즈프로필 링크(참고용)'] ?? ''
}}));
